$enterprise=null;$server=null;foreach(array_slice($argv,1)as$a){if(str_starts_with($a,'--enterprise='))$enterprise=substr($a,13);elseif(str_starts_with($a,'--server='))$server=substr($a,9);}if(!$enterprise||!$server){fwrite(STDERR,"Usage: php DATAFORM_LICENSE_SECURITY_GATE.php --enterprise=... --server=...\n");exit(2);} $enterprise=rtrim($enterprise,'/\\');$server=rtrim($server,'/\\');$checks=[];$c=function($n,$ok,$d='')use(&$checks){$checks[]=[$n,(bool)$ok,$d];};$c('enterprise licensing client',is_file($enterprise.'/system/licensing/LicenseApiClient.php'));$c('runtime bridge',is_file($enterprise.'/system/licensing/EnterpriseRuntimeBridge.php'));$records=is_file($enterprise.'/products/dataform/records.php')?(string)file_get_contents($enterprise.'/products/dataform/records.php'):'';$c('records runtime boot',str_contains($records,'EnterpriseRuntimeBridge::boot('));$c('records write authorization',str_contains($records,'EnterpriseRuntimeBridge::authorizePost('));$protected=['DataFormCompiler.php','ActionResolver.php','DefinitionValidator.php','DesignerService.php','RuntimeManifestBuilder.php','CapabilityResolver.php','RelationResolver.php','EventResolver.php','ServerSigner.php'];$found=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($enterprise,FilesystemIterator::SKIP_DOTS));foreach($it as$f){if($f->isFile()&&in_array($f->getFilename(),$protected,true))$found[]=$f->getPathname();}$c('protected server core absent from enterprise',count($found)===0,implode(';',$found));$secretPatterns=['BEGIN PRIVATE KEY','BEGIN RSA PRIVATE KEY','EASYIT_SERVER_PRIVATE_KEY','server-private.key'];$secretFound=[];foreach($it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($enterprise,FilesystemIterator::SKIP_DOTS)) as$f){if(!$f->isFile()||$f->getSize()>3_000_000)continue;$txt=@file_get_contents($f->getPathname());if($txt===false)continue;foreach($secretPatterns as$p)if(str_contains($txt,$p)&&!str_contains($f->getPathname(),'licensing.example'))$secretFound[]=$f->getPathname().':'.$p;}$c('no server private material in enterprise',count($secretFound)===0,implode(';',$secretFound));$c('server compiler exists',is_file($server.'/src/ProtectedCore/DataFormCompiler.php'));$c('server action resolver exists',is_file($server.'/src/ProtectedCore/ActionResolver.php'));$c('server signer exists',is_file($server.'/src/Security/ServerSigner.php'));$c('server public webroot isolated',is_dir($server.'/public')&&!is_file($server.'/public/../public/server-private.key'));$fail=0;foreach($checks as[$n,$ok,$d]){echo str_pad($n,48).($ok?'PASS':'FAIL').($d!==''?' '.$d:'').PHP_EOL;if(!$ok)$fail++;}echo "FINAL STATUS: ".($fail?'FAILED':'PASSED').PHP_EOL;exit($fail?1:0);
